# Code snippet to demonstrate in-place modification and potential side effects
original_header = {'Content-Type': 'text/html'}
def modify_header(header, info_type, info_content):
    if info_type == 'lang':
        header['Accept-Language'] = info_content
    return header

modified_header = modify_header(original_header, 'lang', 'en-US')
print("Original header:", original_header)
print("Modified header:", modified_header)
# Output shows that original_header is modified in-place
